            arcs=[c for c in reader.collections if c['type']=='arc_kubernetes_cluster' and c['scope'].lower()==scope]
            if len(arcs)!=1 or arcs[0]['status'] not in ('collected','empty') or arcs[0]['items']:
                raise AzureReadError('aks_Arc_workload_universe_unresolved')
            parents=[c for c in reader.collections if c['type']=='aks_cluster' and c['scope'].lower()==scope]
            if len(parents)!=1 or parents[0]['status'] not in ('collected','empty'):
                raise AzureReadError('aks_cluster_inventory_incomplete')
            ids=set()
            for listed in parents[0]['items']:
                rid=_arm(listed.get('id'))
                if rid in ids:raise ValueError('AKS duplicate parent identity')
                ids.add(rid)
            if set(contexts).intersection({r for r in contexts if r.startswith(scope+'/')})!=ids:
                raise AzureReadError('aks_cluster_credentials_incomplete_or_foreign')
            for listed in parents[0]['items']:
                rid=_arm(listed.get('id'))
                rows,proof=_cluster(reader,transport,request,listed,scope,contexts[rid],active,bool(options.get('hosted')))
                for kind,values in rows.items():by_type[kind].extend(values)
                if reader.budget.max_items is not None and reader.total+sum(map(len,by_type.values()))>reader.budget.max_items:
                    raise AzureReadError('resource_limit')
                if any(p['_provenance']['cluster_uid']==proof['_provenance']['cluster_uid'] for p in clusters):
                    raise AzureReadError('aks_cluster_uid_bound_to_multiple_ARM_resources')
                clusters.append(proof)
            if 'kubernetes_scope' in active:
                by_type['kubernetes_scope']=[{'id':scope+'/aks-workloads', 'clusters':clusters}]
            if len(clusters)==1:
                metadata['cluster_id']=clusters[0]['id']
            elif 'service' in active:
                service_error={'code':'aks_service_policy_multicluster_unsupported'}
        except Exception as exc:
            status,error=_safe_error(exc)
            if getattr(exc,'aks_capture_partial',False):status='partial'
            if status in ('collected','empty'):status='unknown'
            # Never publish a truncated universe as complete, including failed UID postchecks.
            by_type={k:[] for k in active}
        for kind,items in sorted(by_type.items()):
            envelope={'type':kind,'scope':scope,'service':'Kubernetes.core/v1' if kind=='service' else 'kubernetes','status':status if error else 'collected' if items else 'empty','items':items}
            if error:envelope['error']=error
            elif kind=='service' and service_error:
                envelope.update(status='not_collected',items=[],error=service_error)
            reader.collections.append(envelope);reader.total+=len(envelope['items']);reader.progress(scope=scope,settled=envelope)
    for scope,policy in policies.items():
        if scope not in {s.lower() for s in scopes}:raise ValueError('AKS policy outside selected subscription')
        if 'limits' in policy:metadata.setdefault('sw25_policy',{})[LIMITS]={'scope':scope,**policy['limits']}
        if 'images' in policy:metadata.setdefault('sw25_policy',{})[IMAGES]={'scope':scope,**policy['images']}
        if 'service_ports' in policy and metadata.get('cluster_id')==policy['service_ports']['cluster_id']:
            metadata.setdefault('sw22',{})['approved_service_ports']={'status':'collected','scope':scope,**policy['service_ports']}
    reader.native_aks_workloads_metadata=metadata

def normalize(options, auth=None):
    """Validate pure normative policy and explicit credentials before any transport."""
    if not isinstance(options, dict) or auth is not None and not isinstance(auth, dict):
        raise ValueError('AKS options and credentials must be objects')
    parent = options.get('compliance_parameters', {})
    if not isinstance(parent, dict):
        raise ValueError('AKS policy parameters invalid')
    raw = parent.get(OPTION)
    output = {}
    if raw is not None:
        try:bounded=len(json.dumps(raw,allow_nan=False))<=50000
        except (TypeError,ValueError):bounded=False
        if not bounded:raise ValueError('AKS owner policy byte budget exceeded')
        if not isinstance(raw, dict) or set(raw) != {'subscriptions'} or not isinstance(raw['subscriptions'], list) or not 0 < len(raw['subscriptions']) <= 16:
            raise ValueError('AKS owner policy subscriptions invalid')
        for row in raw['subscriptions']:
            if not isinstance(row, dict) or not {'scope'} < set(row) or set(row) - {'scope', 'images', 'service_ports', 'limits'}:
                raise ValueError('AKS owner policy fields invalid')
            scope = _scope(row['scope'])
            if scope in output:
                raise ValueError('AKS duplicate owner subscription')
            cleaned = {'scope': scope}
            if 'images' in row:
                image = row['images']
                required = {'mode', 'allowed', 'immutableImages', 'containerKinds'}
                if (not isinstance(image, dict) or not required <= set(image)
                        or set(image) - required - {'allowedDigests'} or image['mode'] not in ('images', 'registries', 'digests')
                        or type(image['immutableImages']) is not bool):
                    raise ValueError('AKS image approval fields invalid')
                _strings(image['allowed']); kinds = _strings(image['containerKinds'], 3)
                if 'containers' not in kinds or set(kinds) - {'containers', 'initContainers', 'ephemeralContainers'}:
                    raise ValueError('AKS container applicability invalid')
                from peaso.checks.compliance_new_sw25_pods import _image
                if image['mode'] == 'images':
                    for value in image['allowed']:
                        try:_image(value)
                        except Exception:raise ValueError('AKS image reference invalid') from None
                if image['mode'] == 'registries' and any(not re.fullmatch(r'[a-z0-9][a-z0-9.-]*(?::[0-9]+)?', x) for x in image['allowed']):
                    raise ValueError('AKS registry approval invalid')
                if image['mode'] == 'digests' and any(not re.fullmatch(r'sha256:[a-f0-9]{64}', x) for x in image['allowed']):
                    raise ValueError('AKS digest approval invalid')
                if image['immutableImages'] or 'allowedDigests' in image:
                    if any(not re.fullmatch(r'sha256:[a-f0-9]{64}', x) for x in _strings(image.get('allowedDigests'))):
                        raise ValueError('AKS immutable digest approval invalid')
                cleaned['images'] = copy.deepcopy(image)
            if 'limits' in row:
                limits = row['limits']
                if not isinstance(limits, dict) or set(limits) != {'maxCpu', 'maxMemory', 'containerKinds'}:
                    raise ValueError('AKS limits approval fields invalid')
                from peaso.checks.compliance_new_sw25_pods import _quantity
                for resource in ('maxCpu', 'maxMemory'):
                    try:_quantity(limits[resource])
                    except Exception:raise ValueError('AKS maximum resource quantity invalid') from None
                kinds = _strings(limits['containerKinds'], 3)
                if 'containers' not in kinds or set(kinds) - {'containers', 'initContainers', 'ephemeralContainers'}:
                    raise ValueError('AKS limits container applicability invalid')
                cleaned['limits'] = copy.deepcopy(limits)
            if 'service_ports' in row:
                ports = row['service_ports']
                if not isinstance(ports, dict) or set(ports) != {'cluster_id', 'services', 'evidence_ref'} or _arm(ports['cluster_id']).split('/resourcegroups/')[0] != scope:
                    raise ValueError('AKS port policy identity invalid')
                if not isinstance(ports['evidence_ref'], str) or not 0 < len(ports['evidence_ref']) <= 512:
                    raise ValueError('AKS port approval reference required')
                services = ports['services']
                if not isinstance(services, list) or len(services) > 1000:
                    raise ValueError('AKS service approval bounds invalid')
                seen = set()
                for service in services:
                    if not isinstance(service, dict) or set(service) != {'namespace', 'name', 'allowed'}:
                        raise ValueError('AKS service approval fields invalid')
                    key = (service['namespace'], service['name'])
                    if any(not isinstance(v, str) or not re.fullmatch(r'[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?', v) for v in key) or key in seen:
                        raise ValueError('AKS service approval identity invalid')
                    seen.add(key); pairs = service['allowed']
                    if not isinstance(pairs, list) or len(pairs) > 256:
                        raise ValueError('AKS service port bounds invalid')
                    unique = set()
                    for pair in pairs:
                        if not isinstance(pair, dict) or set(pair) != {'port', 'protocol'} or type(pair['port']) is not int or not 1 <= pair['port'] <= 65535 or pair['protocol'] not in ('TCP','UDP','SCTP') or (pair['port'],pair['protocol']) in unique:
                            raise ValueError('AKS service port approval invalid')
                        unique.add((pair['port'],pair['protocol']))
                cleaned['service_ports'] = copy.deepcopy(ports)
                cleaned['service_ports']['cluster_id'] = _arm(ports['cluster_id'])
            output[scope] = cleaned
    contexts = {}
    if auth is not None and 'aks_workloads' in auth:
        entries = auth['aks_workloads']
        try:bounded=len(json.dumps(entries,allow_nan=False))<=2000000
        except (TypeError,ValueError):bounded=False
        if not bounded:raise ValueError('AKS credential byte budget exceeded')
        if not isinstance(entries, list) or not 0 < len(entries) <= 16:
            raise ValueError('AKS explicit credential bounds invalid')
        from cryptography import x509
        endpoints=set()
        for entry in entries:
            if not isinstance(entry, dict) or set(entry) != {'cluster_id', 'server', 'ca_cert_data', 'token'}:
                raise ValueError('AKS explicit credential fields invalid')
            rid = _arm(entry['cluster_id']); _server(entry['server'])
            if entry['server'] in endpoints:raise ValueError('AKS endpoint bound to multiple resource identities')
            endpoints.add(entry['server'])
            if rid in contexts:
                raise ValueError('AKS duplicate credential binding')
            token, ca = entry['token'], entry['ca_cert_data']
            if not isinstance(token, str) or not 0 < len(token) <= 1000000 or not token.isascii() or any(c.isspace() or ord(c) < 33 or ord(c) > 126 for c in token):
                raise ValueError('AKS explicit bearer token invalid')
            if not isinstance(ca, str) or not 0 < len(ca) <= 100000 or 'PRIVATE KEY' in ca:
                raise ValueError('AKS inline CA certificate invalid')
            try:
                certs=x509.load_pem_x509_certificates(ca.encode())
                if not certs or any(not cert.extensions.get_extension_for_class(x509.BasicConstraints).value.ca for cert in certs):
                    raise ValueError('AKS trust anchor must be a CA')
            except Exception:raise ValueError('AKS inline CA certificate invalid') from None
            contexts[rid] = copy.deepcopy(entry)
    return output, contexts

def required_types(wanted):
    needed = {'aks_cluster', 'arc_kubernetes_cluster', 'subscription'} if set(wanted).intersection(NATIVE_TYPES) else set()
    if 'pod_runtime' in wanted:needed.add('pod')
    if 'aks_legacy_pod_inventory' in wanted:needed.update(('pod','kubernetes_scope'))
    return needed

peaso.collectors.k8s._native.body:
def _native(item, kind, cluster, scope, namespaced):
    if not isinstance(item, dict) or not isinstance(item.get("metadata"), dict):
        raise ValueError("malformed Kubernetes object")
    if kind == "namespace":
        # GET /api/v1/namespaces fixes the GVK even when list items omit TypeMeta.
        # Reject a supplied, conflicting TypeMeta instead of silently replacing it.
        if item.get("kind", "Namespace") != "Namespace" or item.get("apiVersion", "v1") != "v1":
            raise ValueError("namespace object type conflicts with endpoint")
        item = {**item, "kind": "Namespace", "apiVersion": "v1"}
    meta = item["metadata"]
    name, namespace = meta.get("name"), meta.get("namespace")
    if not isinstance(name, str) or not name or (namespaced and (not isinstance(namespace, str) or not namespace)):
        raise ValueError("missing Kubernetes identity")
    if namespaced and scope != "*" and namespace != scope:
        raise ValueError("object outside requested namespace")
    if not namespaced and namespace:
        raise ValueError("cluster object has namespace")
    namespace = namespace if namespaced else "_cluster"
    result = _sanitize(item)
    annotations = meta.get("annotations", {})
    if isinstance(annotations, dict):
        mirror = annotations.get("kubernetes.io/config.mirror")
        source = annotations.get("kubernetes.io/config.source")
        result["_static_pod_metadata"] = bool(isinstance(mirror, str) and re.fullmatch(r"[0-9a-fA-F]{16,64}", mirror) or source in ("file", "http"))
    result["id"] = "k8s://" + "/".join(quote(str(x), safe="") for x in (cluster, kind, namespace, meta.get("uid") or name))
    result["provenance"] = {"cluster_id": cluster, "namespace": namespace, "uid": meta.get("uid"),
                            "apiVersion": item.get("apiVersion"), "resourceVersion": meta.get("resourceVersion"),
                            "evidence": "read-only list", "credential_material": "omitted"}
    return result

peaso.collectors.k8s._new_api.body:
def _new_api(auth):
    if auth.get('_hosted'):
        auth = hosted_auth(auth)
    from kubernetes import client, config
    from bluepeass.k8s import KubernetesApi
    method = auth.get("method", "auto")
    if method == "inline":
        if auth.get("kubeconfig_data") is None:
            raise ValueError("inline authentication requires kubeconfig_data")
        method = "kubeconfig"
    if method not in ("auto", "kubeconfig", "context", "in_cluster", "in-cluster", "token", "certificate", "client-cert", "direct"):
        raise ValueError("unsupported Kubernetes authentication method")
    if method in ("token", "certificate", "client-cert", "direct") and not auth.get("server"):
        raise ValueError("selected direct authentication requires server")
    if method in ("auto", "kubeconfig", "context") and auth.get("kubeconfig_data") is not None:
        auth = {**auth, **validate_inline_kubeconfig(auth["kubeconfig_data"], auth.get("context"))}
        method = 'direct'
    elif method in ('kubeconfig', 'context') or (method == 'auto' and not auth.get('server')
            and not auth.get('in_cluster') and not os.getenv('KUBERNETES_SERVICE_HOST')):
        # Parse local files as data too. Never call the SDK kubeconfig loader,
        # which can execute exec/auth-provider helpers and read referenced files.
        path = auth.get('kubeconfig') or os.getenv('KUBECONFIG') or os.path.expanduser('~/.kube/config')
        if not isinstance(path, str) or os.pathsep in path:
            raise ValueError('use one data-only kubeconfig file')
        with open(path, encoding='utf-8') as stream:
            raw = stream.read(2_000_001)
        auth = {**auth, **validate_inline_kubeconfig(raw, auth.get('context'))}
        method = 'direct'
    direct = None if method in ("in_cluster", "in-cluster") or (method in ("kubeconfig", "context") and auth.get("kubeconfig_data") is None) else auth.get("server")
    if direct:
        parsed = urlsplit(direct)
        if parsed.scheme != "https" or not parsed.netloc or parsed.username or parsed.query or parsed.fragment:
            raise ValueError("direct Kubernetes server must be an HTTPS origin")
        configuration = client.Configuration()
        configuration.host = direct.rstrip("/")
        configuration.verify_ssl = True
        if auth.get('tls_server_name'):
            configuration.tls_server_name = auth['tls_server_name']
            configuration.assert_hostname = auth['tls_server_name']
        if auth.get("_disable_proxy") is True:
            configuration.proxy = None
            configuration.proxy_headers = None
            configuration.no_proxy = None
        if auth.get("_hosted"):
            configuration.host, hostname = _public_server(direct)
            configuration.tls_server_name = auth.get('tls_server_name') or hostname
            configuration.assert_hostname = auth.get('tls_server_name') or hostname
        if auth.get("ca_cert"):
            configuration.ssl_ca_cert = auth["ca_cert"]
        certificate_mode = method in ("certificate", "client-cert")
        token = None if certificate_mode else auth.get("token")
        if not certificate_mode and auth.get("token_file"):
            with open(auth["token_file"], encoding="utf-8") as stream:
                token = stream.read().strip()
        if token:
            configuration.api_key = {"authorization": token}
            configuration.api_key_prefix = {"authorization": "Bearer"}
        cert, key = auth.get("client_cert"), auth.get("client_key")
        temporary = None
        inline = (("ca_cert_data", "ssl_ca_cert"), ("client_cert_data", "cert_file"), ("client_key_data", "key_file"))
        try:
            if any(auth.get(source) for source, _ in inline):
                temporary = tempfile.TemporaryDirectory(prefix="peaso-k8s-")
                for source, target in inline:
                    value = auth.get(source)
                    if value:
                        if not isinstance(value, str) or len(value) > 1_000_000:
                            raise ValueError("invalid inline TLS material")
                        payload = value.encode() if value.startswith("-----BEGIN") else base64.b64decode(value, validate=True)
                        path = os.path.join(temporary.name, source)
                        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                        with os.fdopen(descriptor, "wb") as stream:
                            stream.write(payload)
                        setattr(configuration, target, path)
        except Exception:
            if temporary:
                temporary.cleanup()
            raise
        cert = cert or configuration.cert_file
        key = key or configuration.key_file
        if bool(cert) != bool(key):
            if temporary:
                temporary.cleanup()
            raise ValueError("client_cert and client_key must be supplied together")
        if cert:
            configuration.cert_file, configuration.key_file = cert, key
        if not token and not cert:
            if temporary:
                temporary.cleanup()
            raise ValueError("direct server requires token, token_file or client certificate")
        api_client = None
        try:
            api_client = client.ApiClient(configuration)
            api = _wrap_client(api_client, direct)
            return _TemporaryApi(api, temporary) if temporary else api
        except Exception:
            try:
                if api_client is not None:
                    api_client.close()
            finally:
                if temporary:
                    temporary.cleanup()
            raise
    elif method in ("in_cluster", "in-cluster") or (method == "auto" and (auth.get("in_cluster") or (not auth.get("kubeconfig") and not auth.get("context") and os.getenv("KUBERNETES_SERVICE_HOST")))):
        configuration = client.Configuration()
        config.load_incluster_config(client_configuration=configuration)
        api_client = client.ApiClient(configuration)
    else:
        raise ValueError('Kubernetes requires explicit credentials or a data-only kubeconfig')
    try:
        return _wrap_client(api_client)
    except Exception:
        api_client.close()
        raise

peaso.collectors.k8s._pages.body:
def _pages(reader, api, path, kind, cluster, scope, namespaced):
    continuation = None
    seen = set()
    node_names, node_uids = set(), set()
    version = None
    for page in count():
        params = {"limit": reader.page_size}
        if continuation:
            params["continue"] = continuation
        response = reader.call(api.get_json, path, params)
        if not isinstance(response, dict) or not isinstance(response.get("items"), list) or not isinstance(response.get("metadata", {}), dict):
            raise ValueError("malformed Kubernetes list")
        if kind == "namespace" and (response.get("kind", "NamespaceList") != "NamespaceList"
                                    or response.get("apiVersion", "v1") != "v1"):
            raise ValueError("namespace list type conflicts with endpoint")
        metadata = response.get("metadata", {})
        current_version = metadata.get("resourceVersion")
        if version is not None and current_version != version:
            raise ValueError("list resourceVersion changed across pages")
        version = current_version
        if kind == "node":
            for item in response["items"]:
                node_meta = item.get("metadata") if isinstance(item, dict) else None
                node_name = node_meta.get("name") if isinstance(node_meta, dict) else None
                node_uid = node_meta.get("uid") if isinstance(node_meta, dict) else None
                if (not isinstance(node_name, str) or not node_name or not isinstance(node_uid, str)
                        or not node_uid):
                    raise K8sReadError("node_identity_missing")
                if node_name in node_names or node_uid in node_uids:
                    raise K8sReadError("duplicate_node_identity")
                node_names.add(node_name)
                node_uids.add(node_uid)
        yield [_native(item, kind, cluster, scope, namespaced) for item in response["items"]]
        continuation = metadata.get("continue")
        if not continuation:
            return
        if not isinstance(continuation, str) or continuation in seen:
            raise ValueError("repeated or malformed continuation")
        seen.add(continuation)
        if reader.budget.max_pages is not None and page + 1 >= reader.budget.max_pages:
            raise K8sReadError("page_limit")

peaso.collectors.k8s._sanitize.body:
def _sanitize(value):
    """Workload literals and last-applied annotations can carry credentials."""
    if isinstance(value, list):
        return [_sanitize(item) for item in value]
    if not isinstance(value, dict):
        return value
    result = {}
    if "command" in value or "args" in value:
        component = _component_config(value)
        if component is not None:
            result["_component_config"] = component
    for key, child in value.items():
        normalized_key = re.sub(r"[^a-z0-9]", "", str(key).lower())
        if (normalized_key != "automountserviceaccounttoken" and normalized_key.endswith(("password", "token", "privatekey", "clientsecret", "secretvalue"))) or normalized_key in (
            "apikey", "credentials", "stringdata", "privatekeydata"):
            continue
        if key in ("managedFields",):
            continue
        if key == "annotations" and isinstance(child, dict):
            # Retain only documented identity, networking and policy provenance.
            nginx_fields = ("nginx.ingress.kubernetes.io/backend-protocol",
                            "nginx.ingress.kubernetes.io/force-ssl-redirect",
                            "nginx.ingress.kubernetes.io/ssl-redirect")
            if any(field in child and (not isinstance(child[field], str) or len(child[field]) > 253)
                   for field in nginx_fields):
                result.setdefault("_coverage", {})["annotations"] = {"status": "malformed"}
            result[key] = {k: v for k, v in child.items() if k in (
                "eks.amazonaws.com/role-arn", "iam.gke.io/gcp-service-account",
                "azure.workload.identity/client-id", "azure.workload.identity/tenant-id",
                "k8s.v1.cni.cncf.io/networks", "k8s.v1.cni.cncf.io/network-status",
                "kubernetes.io/ingress.class", "kubernetes.io/psp", "iam.amazonaws.com/permitted",
                "iam.amazonaws.com/role", "openshift.io/scc", "openshift.io/required-scc", "kubernetes.io/service-account.name",
                "kubernetes.io/service-account.uid") or (isinstance(k, str) and k.startswith(_MANAGED_ANNOTATION_PREFIXES) and isinstance(v, str) and len(v) <= 253)
                or (k in nginx_fields and isinstance(v, str) and len(v) <= 253)}
        elif key == "env" and isinstance(child, list):
            result[key] = [_env_entry(entry) for entry in child if isinstance(entry, dict)]
        elif key in ("command", "args"):
            result[key + "_redacted"] = True
        else:
            result[key] = _sanitize(child)
    return result
